import struct


class gen_isr_parser:
    source_header = """
/* AUTO-GENERATED by gen_isr_tables.py, do not edit! */

#include <zephyr/toolchain.h>
#include <zephyr/linker/sections.h>
#include <zephyr/sw_isr_table.h>
#include <zephyr/arch/cpu.h>

typedef void (* ISR)(const void *);
"""

    source_assembly_header = """
#ifndef ARCH_IRQ_VECTOR_JUMP_CODE
#error "ARCH_IRQ_VECTOR_JUMP_CODE not defined"
#endif
"""

    def __init__(self, intlist_data, config, log):
        """Initialize the parser.

        The function prepares parser to work.
        Parameters:
        - intlist_data: The binnary data from intlist section
        - config: The configuration object
        - log: The logging object, has to have error and debug methods
        """
        self.__config = config
        self.__log = log
        intlist = self.__read_intlist(intlist_data)
        self.__vt, self.__swt, self.__nv = self.__parse_intlist(intlist)

    def __read_intlist(self, intlist_data):
        """read a binary file containing the contents of the kernel's .intList
        section. This is an instance of a header created by
        include/zephyr/linker/intlist.ld:

         struct {
           uint32_t num_vectors;       <- typically CONFIG_NUM_IRQS
           struct _isr_list isrs[]; <- Usually of smaller size than num_vectors
        }

        Followed by instances of struct _isr_list created by IRQ_CONNECT()
        calls:

        struct _isr_list {
            /** IRQ line number */
            int32_t irq;
            /** Flags for this IRQ, see ISR_FLAG_* definitions */
            int32_t flags;
            /** ISR to call */
            void *func;
            /** Parameter for non-direct IRQs */
            const void *param;
        };
        """
        intlist = {}
        prefix = self.__config.endian_prefix()

        # Extract header and the rest of the data
        intlist_header_fmt = prefix + "II"
        header_sz = struct.calcsize(intlist_header_fmt)
        header_raw = struct.unpack_from(intlist_header_fmt, intlist_data, 0)
        self.__log.debug(str(header_raw))

        intlist["num_vectors"] = header_raw[0]
        intlist["offset"] = header_raw[1]
        intdata = intlist_data[header_sz:]

        # Extract information about interrupts
        if self.__config.check_64b():
            intlist_entry_fmt = prefix + "iiQQ"
        else:
            intlist_entry_fmt = prefix + "iiII"

        intlist["interrupts"] = [i for i in struct.iter_unpack(intlist_entry_fmt, intdata)]

        self.__log.debug("Configured interrupt routing")
        self.__log.debug("handler    irq flags param")
        self.__log.debug("--------------------------")

        for irq in intlist["interrupts"]:
            self.__log.debug(f"{hex(irq[2]):<10} {irq[0]:<3} {irq[1]:<3}   {hex(irq[3])}")

        return intlist

    def __parse_intlist(self, intlist):
        """All the intlist data are parsed into swt and vt arrays.

        The vt array is prepared for hardware interrupt table.
        Every entry in the selected position would contain None or the name of the function pointer
        (address or string).

        The swt is a little more complex. At every position it would contain an array of parameter
        and function pointer pairs. If CONFIG_SHARED_INTERRUPTS is enabled there may be more than 1
        entry. If empty array is placed on selected position - it means that the application does
        not implement this interrupt.

        Parameters:
        - intlist: The preprocessed list of intlist section content (see read_intlist)

        Return:
        vt, swt - parsed vt and swt arrays (see function description above)
        """
        nvec = intlist["num_vectors"]
        offset = intlist["offset"]

        if nvec > pow(2, 15):
            raise ValueError('nvec is too large, check endianness.')

        self.__log.debug('offset is ' + str(offset))
        self.__log.debug('num_vectors is ' + str(nvec))

        # Set default entries in both tables
        if not (self.__config.args.sw_isr_table or self.__config.args.vector_table):
            self.__log.error("one or both of -s or -V needs to be specified on command line")
        if self.__config.args.vector_table:
            vt = [None for i in range(nvec)]
        else:
            vt = None
        if self.__config.args.sw_isr_table:
            swt = [[] for i in range(nvec)]
        else:
            swt = None

        # Pre-pass: derive which CPU lines need the 2nd-level dispatcher and
        # which level-2 sources are 3rd-level aggregators, with their densely
        # allocated windows.
        self.__config.note_multilevel_topology(intlist["interrupts"])

        # Process intlist and write to the tables created
        for irq, flags, func, param in intlist["interrupts"]:
            if self.__config.test_isr_direct(flags):
                if not vt:
                    self.__log.error(
                        f"Direct Interrupt {irq} declared with parameter 0x{param:x} "
                        "but no vector table in use"
                    )
                if param != 0:
                    self.__log.error(f"Direct irq {irq} declared, but has non-NULL parameter")
                if not 0 <= irq - offset < len(vt):
                    self.__log.error(
                        f"IRQ {irq - offset} (offset={offset}) exceeds the maximum of {len(vt) - 1}"
                    )
                vt[irq - offset] = func
            else:
                # Regular interrupt
                if not swt:
                    self.__log.error(
                        f"Regular Interrupt {irq} declared with parameter 0x{param:x} "
                        "but no SW ISR_TABLE in use"
                    )

                table_index = self.__config.get_swt_table_index(offset, irq)

                if not 0 <= table_index < len(swt):
                    self.__log.error(
                        f"IRQ {table_index} (offset={offset}) exceeds the maximum of {len(swt) - 1}"
                    )
                if self.__config.check_shared_interrupts():
                    lst = swt[table_index]
                    if (param, func) in lst:
                        self.__log.error("Attempting to register the same ISR/arg pair twice.")
                    if len(lst) >= self.__config.get_sym("CONFIG_SHARED_IRQ_MAX_NUM_CLIENTS"):
                        self.__log.error(
                            "Reached shared interrupt client limit. Maybe increase"
                            + " CONFIG_SHARED_IRQ_MAX_NUM_CLIENTS?"
                        )
                else:
                    if len(swt[table_index]) > 0:
                        self.__log.error(
                            f"multiple registrations at table_index {table_index} for irq {irq} "
                            + f" (0x{irq:x})"
                            + f"\nExisting handler 0x{swt[table_index][0][1]:x}, "
                            + f"new handler 0x{func:x}"
                            + "\nHas IRQ_CONNECT or IRQ_DIRECT_CONNECT accidentally been invoked "
                            + "on the same irq multiple times?"
                        )
                swt[table_index].append((param, func))

        return vt, swt, nvec

    def __write_code_irq_vector_table(self, fp):
        fp.write(self.source_assembly_header)

        fp.write("void __irq_vector_table __attribute__((naked)) _irq_vector_table(void) {\n")
        for i in range(self.__nv):
            func = self.__vt[i]

            if func is None:
                func = self.__config.vt_default_handler

            if isinstance(func, int):
                func_as_string = self.__config.get_sym_from_addr(func)
            else:
                func_as_string = func

            fp.write(f"\t__asm(ARCH_IRQ_VECTOR_JUMP_CODE({func_as_string}));\n")
        fp.write("}\n")

    def __write_address_irq_vector_table(self, fp):
        fp.write(f"const uintptr_t __irq_vector_table _irq_vector_table[{self.__nv}] = {{\n")
        for i in range(self.__nv):
            func = self.__vt[i]

            if func is None:
                func = self.__config.vt_default_handler

            if isinstance(func, int):
                fp.write(f"\t{func},\n")
            else:
                fp.write(f"\t((uintptr_t)&{func}),\n")

        fp.write("};\n")

    def __write_shared_table(self, fp):
        if not self.__config.check_sym("CONFIG_DYNAMIC_INTERRUPTS"):
            fp.write("const ")
        fp.write(
            "struct z_shared_isr_table_entry __shared_sw_isr_table"
            f" z_shared_sw_isr_table[{self.__nv}] = {{\n"
        )

        for i in range(self.__nv):
            if self.__swt[i] is None:
                client_num = 0
                client_list = None
            else:
                client_num = len(self.__swt[i])
                client_list = self.__swt[i]

            if client_num <= 1:
                fp.write("\t{ },\n")
            else:
                fp.write(f"\t{{ .client_num = {client_num}, .clients = {{ ")
                for j in range(0, client_num):
                    routine = client_list[j][1]
                    arg = client_list[j][0]

                    fp.write(
                        f"{{ .isr = (ISR){hex(routine) if isinstance(routine, int) else routine}, "
                        f".arg = (const void *){hex(arg)} }},"
                    )

                fp.write(" },\n},\n")

        fp.write("};\n")

    def __write_l3_window_table(self, fp):
        """Emit the 3rd-level aggregator windows.

        The generator owns this allocation because it is the only stage that
        sees every connected flag, so it is the only stage that can derive an
        aggregator's status-register mask and pack the windows densely. The SoC
        interrupt controller reads the table back and joins it with the
        devicetree, which supplies the status-register address.

        Emitted whenever the configuration supports 3rd-level interrupts, even
        with nothing connected: a devicetree that declares an aggregator no
        handler ever attaches to is a misconfiguration the driver should report
        against an empty table, not an undefined-symbol link failure.
        """
        windows = self.__config.l3_windows

        if not windows:
            fp.write("/* No 3rd-level aggregator has a handler connected. */\n")
            fp.write("const struct z_isr_l3_window z_isr_l3_windows[1] = { { 0 } };\n")
            fp.write("const size_t z_isr_l3_window_num = 0;\n\n")
            return

        fp.write(f"const struct z_isr_l3_window z_isr_l3_windows[{len(windows)}] = {{\n")
        for (line, src), group in windows:
            catch_all = "true" if group["catch_all"] else "false"
            fp.write(
                f"\t{{ .mask = {group['mask']:#010x}, .win_base = {group['win_base']},"
                f" .l2_src = {src}, .catch_all = {catch_all} }},"
                f" /* CPU line {line} */\n"
            )
        fp.write("};\n")
        fp.write(f"const size_t z_isr_l3_window_num = {len(windows)};\n\n")

    def write_isr_switch_start(self, fp):
        fp.write("void __sw_isr_table ")
        fp.write("get_isr_entry(int irq_index, struct _isr_table_entry *entry)\n")
        fp.write("{\n")
        fp.write("\tswitch (irq_index)\n")
        fp.write("\t{\n")

    def write_isr_case_block(self, fp, i, isr, arg):
        fp.write(f"\t\tcase {i}:\n")
        fp.write("\t\t{\n")
        fp.write(f"\t\t\tentry->isr = (ISR){isr:#x};\n")
        fp.write(f"\t\t\tentry->arg = (const void *){arg};\n")
        fp.write("\t\t\tbreak;\n")
        fp.write("\t\t}\n")

    def write_isr_case_single_irq(self, fp, i):
        arg = f"{self.__swt[i][0][0]:#x}"
        isr = self.__swt[i][0][1]
        self.write_isr_case_block(fp, i, isr, arg)

    def write_isr_case_shared_irq(self, fp, i):
        arg = f"&z_shared_sw_isr_table[{i}]"
        isr = self.__config.swt_shared_handler
        self.write_isr_case_block(fp, i, isr, arg)

    def write_isr_case_l1_dispatcher(self, fp, i):
        fp.write(f"\t\tcase {i}:\n")
        fp.write("\t\t{\n")
        fp.write(f"\t\t\tentry->isr = (ISR){self.__config.swt_l2_dispatcher};\n")
        fp.write(f"\t\t\tentry->arg = (const void *){i:#x};\n")
        fp.write("\t\t\tbreak;\n")
        fp.write("\t\t}\n")

    def write_isr_case_l3_dispatcher(self, fp, i, group):
        fp.write(f"\t\tcase {i}:\n")
        fp.write("\t\t{\n")
        fp.write(f"\t\t\tentry->isr = (ISR){self.__config.swt_l3_dispatcher};\n")
        fp.write(f"\t\t\tentry->arg = (const void *){group['index']:#x};\n")
        fp.write("\t\t\tbreak;\n")
        fp.write("\t\t}\n")

    def write_isr_case_default_block(self, fp):
        fp.write("\t\tdefault:\n")
        fp.write("\t\t{\n")
        fp.write(f"\t\t\tentry->isr = (ISR){self.__config.swt_spurious_handler};\n")
        fp.write("\t\t\tentry->arg = (const void *)0x0;\n")
        fp.write("\t\t\tbreak;\n")
        fp.write("\t\t}\n")
        fp.write("\t}\n")
        fp.write("}\n")

    def write_isr_table_switch(self, fp):
        if any(
            len(self.__swt[i]) == 0 and self.__config.get_l1_dispatcher_line(i)
            for i in range(self.__nv)
        ):
            fp.write(f"extern void {self.__config.swt_l2_dispatcher}(const void *);\n\n")
        if self.__config.l3_windows:
            fp.write(f"extern void {self.__config.swt_l3_dispatcher}(const void *);\n\n")
        if self.__config.emits_l3_windows():
            self.__write_l3_window_table(fp)

        self.write_isr_switch_start(fp)

        for i in range(self.__nv):
            if len(self.__swt[i]) == 0:
                group = self.__config.get_l3_dispatcher_slot(i)
                if self.__config.get_l1_dispatcher_line(i):
                    # CPU line that must vector through the 2nd-level dispatcher
                    self.write_isr_case_l1_dispatcher(fp, i)
                elif group is not None:
                    # Level-2 source that is a 3rd-level aggregator
                    self.write_isr_case_l3_dispatcher(fp, i, group)
                # Unused interrupt - default will be used
                continue
            elif len(self.__swt[i]) == 1:
                # Single interrupt
                self.write_isr_case_single_irq(fp, i)
            else:
                # Shared interrupt
                self.write_isr_case_shared_irq(fp, i)

        self.write_isr_case_default_block(fp)

    def write_isr_table_array(self, fp):
        # Declare the flat-layout dispatchers if any slot of the table is going
        # to reference them (see get_l1_dispatcher_line / get_l3_dispatcher_slot).
        if any(
            len(self.__swt[i]) == 0 and self.__config.get_l1_dispatcher_line(i)
            for i in range(self.__nv)
        ):
            fp.write(f"extern void {self.__config.swt_l2_dispatcher}(const void *);\n\n")
        if self.__config.l3_windows:
            fp.write(f"extern void {self.__config.swt_l3_dispatcher}(const void *);\n\n")
        if self.__config.emits_l3_windows():
            self.__write_l3_window_table(fp)

        if not self.__config.check_sym("CONFIG_DYNAMIC_INTERRUPTS"):
            fp.write("const ")
        fp.write(f"struct _isr_table_entry __sw_isr_table _sw_isr_table[{self.__nv}] = {{\n")

        level2_offset = self.__config.get_irq_baseoffset(2)
        level3_offset = self.__config.get_irq_baseoffset(3)

        for i in range(self.__nv):
            if len(self.__swt[i]) == 0:
                group = self.__config.get_l3_dispatcher_slot(i)
                if self.__config.get_l1_dispatcher_line(i):
                    # CPU line that must vector through the 2nd-level
                    # dispatcher: its slot carries the dispatcher, keyed on the
                    # line number
                    param = f"{i:#x}"
                    func = self.__config.swt_l2_dispatcher
                elif group is not None:
                    # Level-2 source that is a 3rd-level aggregator: its slot
                    # carries the status-register demux, keyed on the window
                    param = f"{group['index']:#x}"
                    func = self.__config.swt_l3_dispatcher
                else:
                    # Not used interrupt
                    param = "0x0"
                    func = self.__config.swt_spurious_handler
            elif len(self.__swt[i]) == 1:
                # Single interrupt
                param = f"{self.__swt[i][0][0]:#x}"
                func = self.__swt[i][0][1]
            else:
                # Shared interrupt
                param = f"&z_shared_sw_isr_table[{i}]"
                func = self.__config.swt_shared_handler

            if isinstance(func, int):
                func_as_string = f"{func:#x}"
            else:
                func_as_string = func

            if i == 0:
                fp.write("\t/* V: level 1, CPU interrupt lines */\n")
            if level2_offset is not None and i == level2_offset:
                fp.write(
                    f"\t/* S: level 2 interrupt sources start here (offset: {level2_offset}) */\n"
                )
            if level3_offset is not None and i == level3_offset:
                fp.write(
                    f"\t/* P: level 3 peripheral signals start here (offset: {level3_offset}) */\n"
                )
            for (line, src), group in self.__config.l3_windows:
                if i == group["win_base"]:
                    fp.write(
                        f"\t/* P-window {group['index']}: level-2 source {src} on CPU line"
                        f" {line}, status mask {group['mask']:#010x} */\n"
                    )

            fp.write(f"\t{{(const void *){param}, (ISR){func_as_string}}}, /* {i} */\n")
        fp.write("};\n")

    def write_source(self, fp):
        fp.write(self.source_header)

        if self.__config.check_shared_interrupts():
            self.__write_shared_table(fp)

        if self.__vt:
            if self.__config.check_sym("CONFIG_IRQ_VECTOR_TABLE_JUMP_BY_ADDRESS"):
                self.__write_address_irq_vector_table(fp)
            elif self.__config.check_sym("CONFIG_IRQ_VECTOR_TABLE_JUMP_BY_CODE"):
                self.__write_code_irq_vector_table(fp)
            else:
                self.__log.error("CONFIG_IRQ_VECTOR_TABLE_JUMP_BY_{ADDRESS,CODE} not set")

        if not self.__swt:
            return

        fp.write("\n")

        if self.__config.get_sym("CONFIG_GEN_SW_ISR_TABLE_ARRAY"):
            self.write_isr_table_array(fp)
        elif self.__config.get_sym("CONFIG_GEN_SW_ISR_TABLE_SWITCH"):
            self.write_isr_table_switch(fp)
        else:
            raise ValueError("Unsupported CONFIG_GEN_SW_ISR_TABLE_TYPE")
